(* [comment removed for export] *)
Lemma AFlatBuf_clm : forall LF ff fp m0 m1 m2 LB bs stb F ds lo sp,
  as_RFS H LF m0 -> fresh_frame H LF 2 ff fp -> aceil <= lo ->
  AFlatBuf LB m1 (stb + 144) F ds -> aapp stb SZ_SPCI_STATE -> fsobj H LF stb SZ_SPCI_STATE ->
  (F <> FB_empty -> fsobj H LF (fb_begin F) (fb_cap F)) ->
  (F <> FB_empty -> fb_end F <= stb \/ stb + SZ_SPCI_STATE <= fb_begin F) ->
  (F <> FB_empty -> fb_end F <= bs \/ bs + SZ_BS <= fb_begin F) ->
  aplace bs SZ_BS -> (bs + SZ_BS <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
