(* [comment removed for export] *)
Lemma APCond_clm : forall LF ff fp m0 m1 m2 bs stb lo sp clk,
  as_RFS H LF m0 -> fresh_frame H LF 2 ff fp -> aceil <= lo ->
  APCond m1 (stb + 192) clk -> aapp stb SZ_SPCI_STATE -> fsobj H LF stb SZ_SPCI_STATE -> (bs + SZ_BS <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
  munch (clm_W lo sp bs stb ff) m1 m2 -> wmono asegs m1 m2 -> APCond m2 (stb + 192) clk.
Proof.
  intros LF ff fp m0 m1 m2 bs stb lo sp clk RF FF CEIL PC APS FO SEPBS MU WM.
  pose proof (ff_facts _ _ _ _ _ FF) as (_ & _ & _ & _ & F1 & F2 & F3 & _ & F4 & F5 & F6 & F7 & F8 & F9 & F10 & F11 & F12 & APF & APP1 & SHFF & SF1 & SF2 & SF3 & NSB).
  fs_nums_in F2. fs_nums_in SF2. pose proof aceil_facts as (AF1 & _).
  pose proof (aapp_bounds _ _ APS ltac:(unfold SZ_SPCI_STATE; lia)) as (S1 & S2 & S3 & S4 & S5).
  pose proof (aapp_not_shadowland _ _ APS) as NSS.
  pose proof (fsobj_windows _ HH _ _ _ _ _ _ _ RF FO FF ltac:(lia) ltac:(unfold SZ_SPCI_STATE; lia) ltac:(lia)) as (DS1 & DS2 & DS3 & DS4). fs_nums_in DS1.
  unfold clm_W, SZ_SPCI_STATE, SZ_BS, AFS_HDR, AFS_FLAGS, AFS_SIZE, AIMG_TOP, AHI_LO, ALOWSH_LO, AAPP_HI in *. rewrite <- SHFF in SF1, SF2.
  eapply APCond_transport; [exact PC| exact MU| exact WM|]. unfold SZ_PCOND. cbn [disjoint_from fst snd].
  split; [clear - DS1; lia|]. split; [clear - NSS SF1 SF2; lia|]. split; [clear - S2 CEIL; lia|].
  split; [clear; lia|]. split; [clear; lia|]. split; [clear - SEPBS; lia| exact I].
Qed.

(* [comment removed for export] *)
Lemma shvis_clm : forall ff fp LF m1 m2 bs stb lo sp cs,
  fresh_frame H LF 2 ff fp -> aceil <= lo ->
  shvis m1 bs (bs + SZ_BS) -> aplace bs SZ_BS -> aapp stb SZ_SPCI_STATE ->
  munch (clm_W lo sp bs stb ff) m1 m2 -> wmono asegs m1 m2 ->
  rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880) cs -> Z.of_nat (cells_size cs) = 32 ->
