Lemma cl_mid : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word)
    (bs stb ioc implb spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S : statev) (ds : list byte)
    (m m2 : mem) (lowpad high : list cell) (tj hjunk : list byte),
  rw_cells asegs m2 spa lowpad -> Z.of_nat (cells_size lowpad) = 16 -> lo + AINTRIN_STACK <= spa -> spa + 128 <= bv_unsigned sp ->
  rw_cells asegs m2 (spa + 16) [C8 (Z_to_bv 64 ff); CB 16 tj] ->
  rw_cells asegs m2 (spa + 40) high -> Z.of_nat (cells_size high) = bv_unsigned sp + -128 - spa ->
  rw_cells asegs m2 (bv_unsigned sp + -88) (cl_saved s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs m2 ff [CB 248 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880)
     [C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0);
      C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0);
      C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0);
      C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0)] ->
  rw_cells asegs m2 fp [C1 (b8 1)] ->
  stk asegs m2 lo spa -> mem_inv asegs m2 ->
  as_RFS H ((2, ff, fp) :: LF) m2 -> fresh_frame H LF 2 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
  as_RFS H LF m ->
  munch (cl_W H lo sp bs stb ff fp) m m2 -> wmono asegs m m2 ->
  rw_cells asegs m2 bs (BasicStreamCells stb) -> bs mod 8 = 0 ->
  AStateBlock LB m2 stb ioc implb S ds -> st_lk S = 0 ->
  (st_fb S <> FB_empty -> fb_end (st_fb S) <= stb \/ stb + SZ_SPCI_STATE <= fb_begin (st_fb S)) ->
  (st_fb S <> FB_empty -> fb_end (st_fb S) <= bs \/ bs + SZ_BS <= fb_begin (st_fb S)) ->
  (bs + SZ_BS <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
  aplace bs SZ_BS -> (bs + SZ_BS <= lo \/ bv_unsigned sp <= bs) -> fsobj H LF bs SZ_BS -> accessible m2 bs SZ_BS -> shvis m2 bs (bs + SZ_BS) ->
  fsobj H LF stb SZ_SPCI_STATE ->
  (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S))) ->
  aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (stream_close_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF bs stb ioc implb lo shi S ds m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) (Z_to_bv 64 bs) s4 s5 s6 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s9 s10 s11 t3' t4' t5' t6')
        F (Z_to_bv 64 ACL_MID) fc None m2 (seg_rom asegs)).
